questions.modelAnswer:
class MiniCfs {
  struct Task { uint64_t vr; int id; uint32_t w; };
  struct Cmp {
    bool operator()(const Task& a, const Task& b) const {
      return a.vr != b.vr ? a.vr < b.vr : a.id < b.id;
    }
  };
  std::set<Task, Cmp> rq_;    // ordered like the kernel's rb-tree
  uint64_t min_vr_ = 0;       // monotonic floor
public:
  void add(int id, uint32_t weight) {
    rq_.insert({min_vr_, id, weight});  // start at min_vruntime, no catch-up bonus
  }
  int run_next(uint64_t slice_ns) {
    if (rq_.empty()) return -1;
    Task t = *rq_.begin();
    rq_.erase(rq_.begin());
    t.vr += slice_ns * 1024 / t.w;      // NICE_0 weight = 1024
    rq_.insert(t);
    min_vr_ = std::max(min_vr_, rq_.begin()->vr);
    return t.id;
  }
};
